import{At as e,mt as t,n,pt as r}from"./chunks/framework.BrKcMR_c.js";var i=JSON.parse(`{"title":"ADR-0004: XcodeGen + xcodebuild CLI builds","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0004-xcodegen-cli-builds.md","filePath":"adrs/0004-xcodegen-cli-builds.md","lastUpdated":1789092097000}`),a={name:`adrs/0004-xcodegen-cli-builds.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0004-xcodegen-xcodebuild-cli-builds" tabindex="-1">ADR-0004: XcodeGen + xcodebuild CLI builds <a class="header-anchor" href="#adr-0004-xcodegen-xcodebuild-cli-builds" aria-label="Permalink to “ADR-0004: XcodeGen + xcodebuild CLI builds”">​</a></h1><p><strong>Status:</strong> Accepted · 2026-08-29</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>Requirement: built with the Xcode CLI, agent-friendly, no IDE-owned project state. A real <code>.app</code> needs an app target (Info.plist, entitlements, asset catalog, signing). Plain <code>swift build</code> can&#39;t produce a first-class bundle. Candidates: raw committed <code>.xcodeproj</code>, XcodeGen, Tuist, swift-bundler.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ul><li><strong>XcodeGen</strong> (<code>project.yml</code> is the source of truth) generating the project; <strong><code>.xcodeproj</code> is gitignored</strong>.</li><li><strong><code>xcodebuild</code></strong> drives builds/tests; <strong>Make</strong> wraps the incantations: <code>gen · build · run · test · lint · verify · release</code>.</li><li>Feature code lives in local SPM packages (<code>Packages/Goat*</code>) so most tests run with plain <code>swift test --package-path</code>: fast, no simulator, no project generation needed.</li><li>Signing: local automatic dev signing for now; Hardened Runtime + notarization wired into <code>make release</code> when we ship (ADR-0007).</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Zero merge conflicts on project files; agents edit YAML, not pbxproj. New checkout: <code>brew install xcodegen &amp;&amp; make run</code>.</li><li>One brew-level tool dependency (xcodegen, currently not installed on the dev machine; M0 step one).</li><li>Tuist&#39;s power (caching, graphs) unneeded at this scale; revisit only if build times hurt.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><p>Committed <code>.xcodeproj</code> (rejected: conflict magnet, agent-hostile), Tuist (rejected: heavier tool for the same job here), swift-bundler (rejected: less mature for full macOS app bundles + asset catalogs).</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};